theorem ZombieDamage.Graph.geodesicReply_iff_commonNeighbor {V : Type} (G : ZombieDamage.Graph V) {u w x : V}
  (h : ZombieDamage.Graph.TwoApart G u w) :
  Iff (ZombieDamage.Graph.GeodesicReply G u w x) (And (ZombieDamage.Graph.adj G u x) (ZombieDamage.Graph.adj G x w))

theorem ZombieDamage.Graph.cleanEdge_forces_reply {V : Type} (G : ZombieDamage.Graph V) {u v w x : V}
  (hc : ZombieDamage.Graph.Clean G v w) (huv : ZombieDamage.Graph.adj G u v) (huw : Ne u w) :
  Iff (ZombieDamage.Graph.GeodesicReply G u w x) (Eq x v)

theorem ZombieDamage.Graph.MetricCertificate.distance {V : Type} {G : ZombieDamage.Graph V}
  (M : ZombieDamage.Graph.MetricCertificate G) (u v : V) :
  ZombieDamage.Graph.Distance G (ZombieDamage.Graph.MetricCertificate.value M u v) u v

theorem ZombieDamage.ShortComponentModel.metricForcesWithin_ambient {N : Nat} {V : Type} {T : ZombieDamage.Task N}
  {G : ZombieDamage.Graph V} (M : ZombieDamage.ShortComponentModel T G) (hg : ZombieDamage.Task.GoodGraph T) {b : Nat}
  {s : ZombieDamage.Position N} (h : ZombieDamage.Task.MetricForcesWithin T hg b s) (D : V → Prop)
  (hD : ZombieDamage.ShortComponentModel.FlagSound M s D) :
  ZombieDamage.FullGame.ForcesWithin G (ZombieDamage.ShortComponentModel.Exit M) b ZombieDamage.FullGame.Phase.survivor
    (ZombieDamage.ShortComponentModel.state M s D)

theorem ZombieDamage.FullGame.canForceDamage_iff_le_number {V : Type} [Fintype V] {G : ZombieDamage.Graph V} {k : Nat}
  (hk : LT.lt 0 k) :
  Iff (ZombieDamage.FullGame.CanForceDamage G k) (LE.le k (ZombieDamage.FullGame.zombieDamageNumber G))

theorem ZombieDamage.FullGame.zombieDamageNumber_eq_card_iff {V : Type} [Fintype V] {G : ZombieDamage.Graph V}
  (hn : LT.lt 0 (Fintype.card V)) :
  Iff (Eq (ZombieDamage.FullGame.zombieDamageNumber G) (Fintype.card V)) (ZombieDamage.FullGame.FullDamage G)
